import sys


def main():
    tokens = sys.stdin.read().split()
    n = int(tokens[0])
    words = tokens[1:1 + n]
    q = int(tokens[1 + n])
    queries = tokens[2 + n:2 + n + q]
    # Sorted characters form the signature shared by all anagrams.
    groups = {}
    for word in words:
        groups.setdefault(''.join(sorted(word)), []).append(word)
    for group in groups.values():
        group.sort()
    # Output can reach tens of MB: write line by line instead of joining everything.
    write = sys.stdout.write
    for query in queries:
        group = groups.get(''.join(sorted(query)))
        if group is None:
            write('0\n')
        else:
            write(str(len(group)) + ' ' + ' '.join(group) + '\n')


