import java.io.*;
import java.util.*;

public class Main {
    static String signature(String s) {
        char[] c = s.toCharArray();
        Arrays.sort(c);
        return new String(c);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.resetSyntax();
        st.wordChars('!', '~');
        st.whitespaceChars(0, ' ');
        st.nextToken();
        int n = Integer.parseInt(st.sval);
        // Sorted characters form the signature shared by all anagrams.
        HashMap<String, ArrayList<String>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            st.nextToken();
            String w = st.sval;
            groups.computeIfAbsent(signature(w), k -> new ArrayList<>()).add(w);
        }
        for (ArrayList<String> g : groups.values()) Collections.sort(g);
        st.nextToken();
        int q = Integer.parseInt(st.sval);
        // Output can reach tens of MB: stream bytes and build each group's line once.
        BufferedOutputStream out = new BufferedOutputStream(System.out, 1 << 16);
        HashMap<ArrayList<String>, byte[]> lines = new HashMap<>();
        for (int i = 0; i < q; i++) {
            st.nextToken();
            ArrayList<String> g = groups.get(signature(st.sval));
            if (g == null) { out.write("0\n".getBytes()); continue; }
            byte[] line = lines.computeIfAbsent(g, k -> {
                StringBuilder sb = new StringBuilder().append(k.size());
                for (String w : k) sb.append(' ').append(w);
                return sb.append('\n').toString().getBytes();
            });
            out.write(line);
        }
        out.flush();
    }
}

package main

import (
	"bufio"
	"os"
	"slices"
	"strconv"
)

func signature(s string) string {
	b := []byte(s)
	slices.Sort(b)
	return string(b)
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	// Sorted characters form the signature shared by all anagrams.
	groups := map[string][]string{}
	for i := 0; i < n; i++ {
		w := next()
		k := signature(w)
		groups[k] = append(groups[k], w)
	}
	for _, g := range groups {
		slices.Sort(g)
	}
	q, _ := strconv.Atoi(next())
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < q; i++ {
		g, ok := groups[signature(next())]
		if !ok {
			w.WriteString("0\n")
			continue
		}
		w.WriteString(strconv.Itoa(len(g)))
		for _, word := range g {
			w.WriteByte(' ')
			w.WriteString(word)
		}
		w.WriteByte('\n')
	}
}
